/**
 * One paired device, as the Devices screen shows it.
 */
public struct DeviceInfo: Equatable, Hashable {
    /**
     * The public key as 64 lowercase hex characters. This is the identity.
     */
    public var keyHex: String
    /**
     * The name it sent in `hello`. Shown, never trusted.
     */
    public var name: String
    /**
     * When it was paired.
     */
    public var pairedUnixSecs: Int64
    /**
     * How it is reachable right now, if at all.
     */
    public var reachableVia: Transport?
    /**
     * Bytes per second moving to or from it in the last second, if any.
     */
    public var speedBytesPerSec: UInt64?
    /**
     * When it was last reachable, if it is not reachable now.
     */
    public var lastSeenUnixSecs: Int64?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The public key as 64 lowercase hex characters. This is the identity.
         */keyHex: String, 
        /**
         * The name it sent in `hello`. Shown, never trusted.
         */name: String, 
        /**
         * When it was paired.
         */pairedUnixSecs: Int64, 
        /**
         * How it is reachable right now, if at all.
         */reachableVia: Transport?, 
        /**
         * Bytes per second moving to or from it in the last second, if any.
         */speedBytesPerSec: UInt64?, 
        /**
         * When it was last reachable, if it is not reachable now.
         */lastSeenUnixSecs: Int64?) {
        self.keyHex = keyHex
        self.name = name
        self.pairedUnixSecs = pairedUnixSecs
        self.reachableVia = reachableVia
        self.speedBytesPerSec = speedBytesPerSec
        self.lastSeenUnixSecs = lastSeenUnixSecs
    }

    

    
}

