     * Bytes verified in place.
     */
    public var bytesDone: UInt64
    /**
     * Where it is.
     */
    public var state: TransferState
    /**
     * Which transport is carrying it, while active.
     */
    public var transport: Transport?
    /**
     * Why it failed or paused, when it did.
     */
    public var error: FerryError?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Stable for the life of the transfer, across restarts.
         */id: String, 
        /**
         * Which device it is with.
         */deviceKeyHex: String, 
        /**
         * The file's name, for display.
         */fileName: String, 
        /**
         * Total size in bytes.
         */bytesTotal: UInt64, 
        /**
         * Bytes verified in place.
         */bytesDone: UInt64, 
        /**
         * Where it is.
         */state: TransferState, 
        /**
         * Which transport is carrying it, while active.
         */transport: Transport?, 
        /**
         * Why it failed or paused, when it did.
         */error: FerryError?) {
        self.id = id
        self.deviceKeyHex = deviceKeyHex
        self.fileName = fileName
        self.bytesTotal = bytesTotal
        self.bytesDone = bytesDone
        self.state = state
        self.transport = transport
        self.error = error
    }

    

    
}

