/**
 * Where pairing is.
 */

public enum PairingState: Equatable, Hashable {
    
    /**
     * Not pairing.
     */
    case idle
    /**
     * Looking for a device, or on the phone, waiting for a Mac.
     */
    case waiting
    /**
     * The Mac has candidates to pick from.
     */
    case found(
        /**
         * What can be picked.
         */candidates: [PairingCandidate]
    )
    /**
     * Both screens show the code.
     */
    case code(
        /**
         * Six digits, zero padded.
         */code: String
    )
    /**
     * Both sides confirmed. The device is now in `devices()`.
     */
    case confirmed(
        /**
         * The new device.
         */device: DeviceInfo
    )
    /**
     * Pairing stopped.
     */
    case failed(
        /**
         * Why.
         */error: FerryError
    )





}

